@import "tailwindcss";

@theme inline {
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-line: var(--line);
  --color-card: var(--card);
  --color-accent: var(--accent);
  --font-sans: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

:root {
  --ink: #2b2d2f;
  --muted: #6f7275;
  --line: #e3ded6;
  --card: #fffdf9;
  --bg: #f6f2ec;
  --accent: #a8553a;
