  it('keeps sessions from every day; today\'s log shows only today, newest first', () => {
    const yesterday = T0 - 24 * 60 * MIN
    let log = sanitizeHistory([{ id: 'old', task: 'old', finishedAt: yesterday, minutes: 25 }])
