    const out = sanitizeHistory([{ id: 1 }, null, { ...ok('z', T0), minutes: 0 }, ok('b', T0 + 1), ok('a', T0)])
    expect(out.map((e) => e.id)).toEqual(['a', 'b'])
  })
})

