function BarChart({ days }: { days: DayStat[] }) {
  const [active, setActive] = useState<number | null>(null)
  const { top, step } = niceScale(Math.max(...days.map((d) => d.minutes)))
  const ticks = Array.from({ length: top / step + 1 }, (_, i) => i * step)

